selector_to_html = {"a[href=\"example-qwen2.5-bv150.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Qwen2.5-1.5B inference on Iluvatar BI-V150<a class=\"headerlink\" href=\"#qwen2-5-1-5b-inference-on-iluvatar-bi-v150\" title=\"Link to this heading\">#</a></h1><h2>Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"example-qwen2.5-bv150.html#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h2><h3>3.1 Component dependencies<a class=\"headerlink\" href=\"#component-dependencies\" title=\"Link to this heading\">#</a></h3>", "a[href=\"example-qwen2.5-bv150.html#inference-scripts\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Inference scripts<a class=\"headerlink\" href=\"#inference-scripts\" title=\"Link to this heading\">#</a></h2><h3>5.1 Basic inference script<a class=\"headerlink\" href=\"#basic-inference-script\" title=\"Link to this heading\">#</a></h3><p>Create <code class=\"docutils literal notranslate\"><span class=\"pre\">run_qwen2.5_1.5b.py</span></code>:</p>", "a[href=\"#getting-started\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Getting Started<a class=\"headerlink\" href=\"#getting-started\" title=\"Link to this heading\">#</a></h1><p>This section covers the requirements for installing vllm-plugin-FL and guides you through installing vllm, vllm-plugin-FL on different hardware platforms, and running a inference task.</p>", "a[href=\"install.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Install software for running an inference task<a class=\"headerlink\" href=\"#install-software-for-running-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>vllm-plugin-FL can be installed from source code or via Docker images.</p>", "a[href=\"run-inference-task.html#run-a-serving-inference-task\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run a serving inference task<a class=\"headerlink\" href=\"#run-a-serving-inference-task\" title=\"Link to this heading\">#</a></h2><p>Serving inference starts a long-running vLLM API server that keeps the model loaded in memory, accepting requests via OpenAI-compatible HTTP endpoints \u2014 ideal for online services and concurrent clients.</p><p>Since this is a local deployment, no API key is required. Set <code class=\"docutils literal notranslate\"><span class=\"pre\">api_key</span></code> to any value (e.g. <code class=\"docutils literal notranslate\"><span class=\"pre\">\"EMPTY\"</span></code>) \u2014 no tokens are consumed.</p>", "a[href=\"example-qwen2.5-bv150.html#model-overview\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Model overview<a class=\"headerlink\" href=\"#model-overview\" title=\"Link to this heading\">#</a></h2><p><strong>Qwen2.5-1.5B</strong> is a small-scale language model from the Alibaba Qwen2.5 series, with approximately 1.5 billion parameters.</p>", "a[href=\"example-qwen2.5-bv150.html#environment-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Environment requirements<a class=\"headerlink\" href=\"#environment-requirements\" title=\"Link to this heading\">#</a></h2><h3>2.1 Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h3><p>Ensure FlagOS components are installed:</p>", "a[href=\"requirements.html#supported-hardware-platforms\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported hardware platforms<a class=\"headerlink\" href=\"#supported-hardware-platforms\" title=\"Link to this heading\">#</a></h2><p>The following table summarizes supported hardware and their verification status:</p>", "a[href=\"install.html#optional-dispatch-operators\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">(Optional) Dispatch operators<a class=\"headerlink\" href=\"#optional-dispatch-operators\" title=\"Link to this heading\">#</a></h2><p>If needed, you can also dispatch operators.</p><p>For concept related information, see <a class=\"reference internal\" href=\"../overview/overview.html\"><span class=\"std std-doc\">vllm-plugin-FL Overview</span></a>.\nFor configuration related information, see <a class=\"reference internal\" href=\"../dispatch_user_guide/dispatch-user-guide.html\"><span class=\"std std-doc\">Operator dispatch user guide</span></a>.</p>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Software Requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2>", "a[href=\"install.html#install-from-docker-image\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from docker image<a class=\"headerlink\" href=\"#install-from-docker-image\" title=\"Link to this heading\">#</a></h2><p>This section covers running vllm-plugin-FL using pre-built Docker images.</p>", "a[href=\"example-qwen2.5-bv150.html#parameter-tuning\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">7. Parameter tuning<a class=\"headerlink\" href=\"#parameter-tuning\" title=\"Link to this heading\">#</a></h2><h3>7.1 LLM initialization parameters<a class=\"headerlink\" href=\"#llm-initialization-parameters\" title=\"Link to this heading\">#</a></h3>", "a[href=\"requirements.html#software-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Software Requirements<a class=\"headerlink\" href=\"#software-requirements\" title=\"Link to this heading\">#</a></h2>", "a[href=\"run-inference-task.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run an inference task<a class=\"headerlink\" href=\"#run-an-inference-task\" title=\"Link to this heading\">#</a></h1><p>With vLLM and vllm-plugin-FL installed, you can run inference in two ways: offline batched inference (load the model directly in a Python script) or serving inference (start an API server and send requests). Choose the approach that fits your use case.</p>", "a[href=\"install.html#install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from source<a class=\"headerlink\" href=\"#install-from-source\" title=\"Link to this heading\">#</a></h2><p>This section covers installing vllm-plugin-FL and its dependencies from source code.</p>", "a[href=\"example-qwen2.5-bv150.html#benchmark-performance\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">8. Benchmark performance<a class=\"headerlink\" href=\"#benchmark-performance\" title=\"Link to this heading\">#</a></h2><h3>8.1 Expected performance of Qwen2.5-1.5B on BV150<a class=\"headerlink\" href=\"#expected-performance-of-qwen2-5-1-5b-on-bv150\" title=\"Link to this heading\">#</a></h3>", "a[href=\"example-qwen2.5-bv150.html#faq\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">9. FAQ<a class=\"headerlink\" href=\"#faq\" title=\"Link to this heading\">#</a></h2><h3>Q1: Model load fails with <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code> error<a class=\"headerlink\" href=\"#q1-model-load-fails-with-symmetric-memory-error\" title=\"Link to this heading\">#</a></h3><p><strong>Cause</strong>: Unsupported symbol in torch-corex. vLLM\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">parallel_state.py</span></code> attempts to import <code class=\"docutils literal notranslate\"><span class=\"pre\">_symmetric_memory</span></code>.</p><p><strong>Solution</strong>:</p>", "a[href=\"example-qwen2.5-bv150.html#contents\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Contents<a class=\"headerlink\" href=\"#contents\" title=\"Link to this heading\">#</a></h2>", "a[href=\"run-inference-task.html#run-an-offline-batched-inference\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Run an offline batched inference<a class=\"headerlink\" href=\"#run-an-offline-batched-inference\" title=\"Link to this heading\">#</a></h2><p>Offline batched inference loads the model directly in a Python script and generates outputs for a batch of prompts in a single run \u2014 no server setup required.</p>", "a[href=\"requirements.html#supported-models\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Supported models<a class=\"headerlink\" href=\"#supported-models\" title=\"Link to this heading\">#</a></h2><p>In theory, vllm-plugin-FL can support all models available in vLLM if no unsupported operators are involved. The following models have been end-to-end verified:</p>", "a[href=\"example-qwen2.5-bv150.html#model-download\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Model download<a class=\"headerlink\" href=\"#model-download\" title=\"Link to this heading\">#</a></h2><h3>4.1 From ModelScope (recommended, domestic access)<a class=\"headerlink\" href=\"#from-modelscope-recommended-domestic-access\" title=\"Link to this heading\">#</a></h3>", "a[href=\"example-qwen2.5-bv150.html#running-instructions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Running instructions<a class=\"headerlink\" href=\"#running-instructions\" title=\"Link to this heading\">#</a></h2><h3>6.1 Direct run<a class=\"headerlink\" href=\"#direct-run\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
